window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1PE"]={"book":"1PE","editions":{"dan-1819":[[1,1,"Peter, Jesu Christi Apostel, til Udlændingene af Adspredelsen i Pontus, Galatien, Cappadocien, Asien og Bithynien,","Peter, Jesu Christi Apostel, til Udlændingene af Adspredelsen i Pontus, Galatien, Cappadocien, Asien og Bithynien,"],[1,2,"udvalgte efter Gud Faders Bestemmelse, i Aandens Helliggjørelse, til Lydighed mod Jesus Christus og Renselse ved hans Blod: Naade og Fred vorde Eder mangfoldigen!","udvalgte efter Gud Faders Bestemmelse, i Aandens Helliggjørelse, til Lydighed mod Jesus Christus og Renselse ved hans Blod: Naade og Fred vorde Eder mangfoldigen!"],[1,3,"Lovet være Gud og vor Herres Jesu Christi Fader, som efter sin store Barmhjertighed haver igjenfødt os til et levende Haab ved Jesu Christi Opstandelse fra de Døde,","Lovet være Gud og vor Herres Jesu Christi Fader, som efter sin store Barmhjertighed haver igjenfødt os til et levende Haab ved Jesu Christi Opstandelse fra de Døde,"],[1,4,"til en uforkrænkelig og ubesmittelig og uforvisnelig Arv, som er bevaret i Himlene til Eder,","til en uforkrænkelig og ubesmittelig og uforvisnelig Arv, som er bevaret i Himlene til Eder,"],[1,5,"hvilke ved Guds magt bevogtes ved Troen til den Frelse, som er rede at aabenbares i den sidste Tid.","hvilke ved Guds magt bevogtes ved Troen til den Frelse, som er rede at aabenbares i den sidste Tid."],[1,6,"Herover fryder Eder, om I og nu en liden Stund, hvis saa skal være, bedrøves i adskillige Fristelser,","Herover fryder Eder, om I og nu en liden Stund, hvis saa skal være, bedrøves i adskillige Fristelser,"],[1,7,"paa det Eders prøvede Tro, (som er meget dyrebarere, end det forgængelige Guld, hvilket dog prøves ved Ilden), maa befindes til Lov og Priis og Ære i Jesu Christi Aabenbarelse,","paa det Eders prøvede Tro, (som er meget dyrebarere, end det forgængelige Guld, hvilket dog prøves ved Ilden), maa befindes til Lov og Priis og Ære i Jesu Christi Aabenbarelse,"],[1,8,"hvem I ikke have kjendt, og dog elske, hvem I nu ikke see, men dog troe paa, og fryde Eder med uudsigelig og forherliget Glæde,","hvem I ikke have kjendt, og dog elske, hvem I nu ikke see, men dog troe paa, og fryde Eder med uudsigelig og forherliget Glæde,"],[1,9,"opnaaende Maalet for Eders Tro, Sjælenes Frelse.","opnaaende Maalet for Eders Tro, Sjælenes Frelse."],[1,10,"Om hvilken Frelse Propheterne have grandsket og ransaget, hvilken have spaaet om den Naade, Eder skulde vederfares;","Om hvilken Frelse Propheterne have grandsket og ransaget, hvilken have spaaet om den Naade, Eder skulde vederfares;"],[1,11,"idet de ransagede, til hvilken eller hvordan en Tid Christi Aand, som var i dem, henviste, da den forud vidende om Christi Lidelser og den derpaa følgende Herlighed.","idet de ransagede, til hvilken eller hvordan en Tid Christi Aand, som var i dem, henviste, da den forud vidende om Christi Lidelser og den derpaa følgende Herlighed."],[1,12,"Thi det var dem aabenbaret, at de ikke for dem selv, men for os besørgede dette, som nu er blevet Eder kundgjort af dem, der have forkyndt Eder Evangelium i den Hellig Aand, som blev sendt af Himmelen; hvilke Ting Englene begjere at gjennemskue.","Thi det var dem aabenbaret, at de ikke for dem selv, men for os besørgede dette, som nu er blevet Eder kundgjort af dem, der have forkyndt Eder Evangelium i den Hellig Aand, som blev sendt af Himmelen; hvilke Ting Englene begjere at gjennemskue."],[1,13,"Derfor omgjorder Eders Sinds Lænder, værer ædrue, og sætter Eders Haab aldeles til den Naade, som bliver Eder til Deel i Jesu Christi Aabenbarelse.","Derfor omgjorder Eders Sinds Lænder, værer ædrue, og sætter Eders Haab aldeles til den Naade, som bliver Eder til Deel i Jesu Christi Aabenbarelse."],[1,14,"Som lydige Børn, skikker Eder ikke efter de forrige Lyster i Eders Vankundighed,","Som lydige Børn, skikker Eder ikke efter de forrige Lyster i Eders Vankundighed,"],[1,15,"men efter den Hellige, som Eder kaldte, vorder og I hellige i al Omgængelse.","men efter den Hellige, som Eder kaldte, vorder og I hellige i al Omgængelse."],[1,16,"Derfor er der skrevet: vorder hellige, thi jeg er hellig.","Derfor er der skrevet: vorder hellige, thi jeg er hellig."],[1,17,"Og dersom I paakalde ham som Fader, der dømmer uden Persons Anseelse efter Enhvers Gjerning, da omgaaes med Frygt i Eders Udlændigheds Tid,","Og dersom I paakalde ham som Fader, der dømmer uden Persons Anseelse efter Enhvers Gjerning, da omgaaes med Frygt i Eders Udlændigheds Tid,"],[1,18,"vidende, at I ikke med forkrænkelige Ting, Sølv eller Guld, ere forløste fra Eders forfængelige Omgængelse, som Fædrene have overantvordet Eder,","vidende, at I ikke med forkrænkelige Ting, Sølv eller Guld, ere forløste fra Eders forfængelige Omgængelse, som Fædrene have overantvordet Eder,"],[1,19,"men med Christi dyrebare Blod, som et ustraffeligt og lydeløst Lams,","men med Christi dyrebare Blod, som et ustraffeligt og lydeløst Lams,"],[1,20,"som vel forud var bestemt, før Verdens Grundvold blev lagt, men blev aabenbaret i disse sidste Tider for Eder,","som vel forud var bestemt, før Verdens Grundvold blev lagt, men blev aabenbaret i disse sidste Tider for Eder,"],[1,21,"som formedelst ham troe paa Gud, der opreiste ham fra de Døde og gav ham Herlighed, saa Eders Tro og Haab maa være til Gud.","som formedelst ham troe paa Gud, der opreiste ham fra de Døde og gav ham Herlighed, saa Eders Tro og Haab maa være til Gud."],[1,22,"Renser Eders Sjæle i Sandheds Lydighed formedelst Aanden, til uskrømtet Broderkjærlighed, og elsker hverandre inderligen af et reent Hjerte,","Renser Eders Sjæle i Sandheds Lydighed formedelst Aanden, til uskrømtet Broderkjærlighed, og elsker hverandre inderligen af et reent Hjerte,"],[1,23,"I, som ere igjenfødte, ikke af forkrænkelig, men uforkrænkelig Sæd ved Guds Ord, som lever og bliver evindeligen.","I, som ere igjenfødte, ikke af forkrænkelig, men uforkrænkelig Sæd ved Guds Ord, som lever og bliver evindeligen."],[1,24,"Thi alt Kjød er som Græs og al Menneskets Herlighed som Græssets Blomster: Græsset visner, og Blomsteret derpaa falder af;","Thi alt Kjød er som Græs og al Menneskets Herlighed som Græssets Blomster: Græsset visner, og Blomsteret derpaa falder af;"],[1,25,"men Herrens Ord bliver evindeligen. Og dette er det Ord, som er forkyndt for Eder.","men Herrens Ord bliver evindeligen. Og dette er det Ord, som er forkyndt for Eder."],[2,1,"Derfor aflægger al Ondskab og al Svig og Hykleri og Avind og al Bagtalelse;","Derfor aflægger al Ondskab og al Svig og Hykleri og Avind og al Bagtalelse;"],[2,2,"og higer som nyfødte Børn efter den aandelige uforfalskede Mælk, at I kunne voxe ved den,","og higer som nyfødte Børn efter den aandelige uforfalskede Mælk, at I kunne voxe ved den,"],[2,3,"dersom I ellers have smagt, at Herren er god.","dersom I ellers have smagt, at Herren er god."],[2,4,"Kommer til ham, den levende Steen, der vel blev forskudt af Menneskene, men er udvalgt og dyrebar for Gud,","Kommer til ham, den levende Steen, der vel blev forskudt af Menneskene, men er udvalgt og dyrebar for Gud,"],[2,5,"og vorder selv som levende Stene, opbyggede til at vorde et aandeligt Huus, til et helligt Præstedom, at frembære aandelige Offere, velbehagelige for Gud ved Jesus Christus.","og vorder selv som levende Stene, opbyggede til at vorde et aandeligt Huus, til et helligt Præstedom, at frembære aandelige Offere, velbehagelige for Gud ved Jesus Christus."],[2,6,"Derfor hedder det og i Skriften: see, jeg sætter i Zion en Hovedhjørnesteen som er udvalgt og dyrebar; og hvo, som troer paa ham, skal ingenlunde beskæmmes.","Derfor hedder det og i Skriften: see, jeg sætter i Zion en Hovedhjørnesteen som er udvalgt og dyrebar; og hvo, som troer paa ham, skal ingenlunde beskæmmes."],[2,7,"Eder, altsaa, som troe, tilkommer denne Ære; men for de Vantroe er denne Steen, hvilken Bygningsmændene forstøde, bleven til en Hovedhjørnesteen og en Anstødsteen og en Forargelses Klippe;","Eder, altsaa, som troe, tilkommer denne Ære; men for de Vantroe er denne Steen, hvilken Bygningsmændene forstøde, bleven til en Hovedhjørnesteen og en Anstødsteen og en Forargelses Klippe;"],[2,8,"hvilke støde an, idet de ikke troe Ordet, hvortil de og vare bestemte.","hvilke støde an, idet de ikke troe Ordet, hvortil de og vare bestemte."],[2,9,"Men I ere en udvalgt Slægt, et kongeligt Præstedom, et helligt Folk, et Folk til Eiendom, at I skulle forkynde hans Dyder, som kaldte Eder fra Mørket til sit beundringsværdige Lys,","Men I ere en udvalgt Slægt, et kongeligt Præstedom, et helligt Folk, et Folk til Eiendom, at I skulle forkynde hans Dyder, som kaldte Eder fra Mørket til sit beundringsværdige Lys,"],[2,10,"I, som fordum ikke var et Folk, men nu ere Guds Folk; som ikke havde erholdt Barmhjertighed, men nu have fundet Barmhjertighed.","I, som fordum ikke var et Folk, men nu ere Guds Folk; som ikke havde erholdt Barmhjertighed, men nu have fundet Barmhjertighed."],[2,11,"I Elskelige! jeg formaner Eder som Fremmede og Udlændinge, at I holde Eder fra kjødelige Lyster, som stride imod Sjælen.","I Elskelige! jeg formaner Eder som Fremmede og Udlændinge, at I holde Eder fra kjødelige Lyster, som stride imod Sjælen."],[2,12,"Eders Omgængelse være god iblandt Hedningerne, at de, idet de bagtale Eder som Misdædere, kunne see Eders gode Gjerninger, og derover prise Gud paa Besøgelsens Dag.","Eders Omgængelse være god iblandt Hedningerne, at de, idet de bagtale Eder som Misdædere, kunne see Eders gode Gjerninger, og derover prise Gud paa Besøgelsens Dag."],[2,13,"Værer derfor al menneskelig Orden underdanige for Herrens Skyld; være sig en Konge, som den Ypperste,","Værer derfor al menneskelig Orden underdanige for Herrens Skyld; være sig en Konge, som den Ypperste,"],[2,14,"eller Befalingsmænd, som de, der sendes af ham til Straf over Misdædere, men dem til Lov, som gjøre Godt.","eller Befalingsmænd, som de, der sendes af ham til Straf over Misdædere, men dem til Lov, som gjøre Godt."],[2,15,"Thi saaledes er det Guds Villie, at I, ved at gjøre det Gode, skulle bringe de daarlige Menneskers Vankundighed til at tie;","Thi saaledes er det Guds Villie, at I, ved at gjøre det Gode, skulle bringe de daarlige Menneskers Vankundighed til at tie;"],[2,16,"som de, der ere frie, dog ikke som de, der have Friheden til Ondskabs Skjul, men som Guds Tjenere.","som de, der ere frie, dog ikke som de, der have Friheden til Ondskabs Skjul, men som Guds Tjenere."],[2,17,"Ærer Alle; elsker Broderskabet; frygter Gud; ærer Kongen!","Ærer Alle; elsker Broderskabet; frygter Gud; ærer Kongen!"],[2,18,"I Tjenere! værer Eders Herrer underdanige i al Ærefrygt, ikke alene de gode og billige, men ogsaa de fortrædelige.","I Tjenere! værer Eders Herrer underdanige i al Ærefrygt, ikke alene de gode og billige, men ogsaa de fortrædelige."],[2,19,"Thi dette finder Naade, dersom Nogen af Samvittighed for Gud fordrager Gjenvordigheder, naar han lider uretfærdeligen.","Thi dette finder Naade, dersom Nogen af Samvittighed for Gud fordrager Gjenvordigheder, naar han lider uretfærdeligen."],[2,20,"Thi hvad er det for en Roes, dersom I, naar I synde og blive slagne, lide taalmodeligen? Men dersom I, naar I gjøre Godt og lide derfor, ere taalmodige, dette finder Naade for Gud.","Thi hvad er det for en Roes, dersom I, naar I synde og blive slagne, lide taalmodeligen? Men dersom I, naar I gjøre Godt og lide derfor, ere taalmodige, dette finder Naade for Gud."],[2,21,"Thi dertil ere I kaldte, efterdi Christus haver og lidt for os, efterladende os et Exempel, at I skulle efterfølge hans Fodspor;","Thi dertil ere I kaldte, efterdi Christus haver og lidt for os, efterladende os et Exempel, at I skulle efterfølge hans Fodspor;"],[2,22,"hvilken ikke haver gjort Synd, der blev og ikke funden Svig i hans Mund;","hvilken ikke haver gjort Synd, der blev og ikke funden Svig i hans Mund;"],[2,23,"hvilken ikke skjendte igjen, der han blev overskjendt, ikke truede, der han led, men overgav det til ham, som dømmer retfærdeligen;","hvilken ikke skjendte igjen, der han blev overskjendt, ikke truede, der han led, men overgav det til ham, som dømmer retfærdeligen;"],[2,24,"hvilken selv bar vore Synder paa sit Legeme paa Træet, paa det vi, afdøde fra Synden, skulle leve i Retfærdighed; ved hans Saar ere I lægte.","hvilken selv bar vore Synder paa sit Legeme paa Træet, paa det vi, afdøde fra Synden, skulle leve i Retfærdighed; ved hans Saar ere I lægte."],[2,25,"Thi I vare som vildfarende Faar, men ere nu omvendte til Eders Sjæles Hyrde og Tilsynsmand.","Thi I vare som vildfarende Faar, men ere nu omvendte til Eders Sjæles Hyrde og Tilsynsmand."],[3,1,"Desligeste, I Kvinder! værer Eders Ægtemænd underdanige, paa det og, dersom Nogle ikke troe Ordet de kunne vindes uden Ord ved Kvindernes Omgængelse,","Desligeste, I Kvinder! værer Eders Ægtemænd underdanige, paa det og, dersom Nogle ikke troe Ordet de kunne vindes uden Ord ved Kvindernes Omgængelse,"],[3,2,"naar de skue Eders kydske Omgængelse i Herrens Frygt.","naar de skue Eders kydske Omgængelse i Herrens Frygt."],[3,3,"Eders Prydelse skal ikke være den udvortes, Haarfletning og paahængte Guldsmykker eller Klædedragt,","Eders Prydelse skal ikke være den udvortes, Haarfletning og paahængte Guldsmykker eller Klædedragt,"],[3,4,"men Hjertets skjulte Menneske i en sagtmodig og stille Aands uforkrænkelige Væsen , hvilket er meget kosteligt for Gud.","men Hjertets skjulte Menneske i en sagtmodig og stille Aands uforkrænkelige Væsen , hvilket er meget kosteligt for Gud."],[3,5,"Thi saaledes prydede sig og fordum de hellige Kvinder, som haabede paa Gud og vare deres Ægtemænd underdanige,","Thi saaledes prydede sig og fordum de hellige Kvinder, som haabede paa Gud og vare deres Ægtemænd underdanige,"],[3,6,"som Sara var Abraham lydig og kaldte ham Herre; og hendes Børn ere I blevne, dersom I gjøre Godt og ikke frygte for nogen Rædsel.","som Sara var Abraham lydig og kaldte ham Herre; og hendes Børn ere I blevne, dersom I gjøre Godt og ikke frygte for nogen Rædsel."],[3,7,"Desligeste, I Mænd! lever med Eders Hustruer som med den svagere Deel, med Forstand, og beviser dem Ære, da de ogsaa ere Medarvinger til Livets Naadegave, paa det Eders Bønner ikke skulle forhindres.","Desligeste, I Mænd! lever med Eders Hustruer som med den svagere Deel, med Forstand, og beviser dem Ære, da de ogsaa ere Medarvinger til Livets Naadegave, paa det Eders Bønner ikke skulle forhindres."],[3,8,"Overhovedet, værer alle ligesindede, medlidende, kjærlige mod Brødrene, barmhjertige, velvillige;","Overhovedet, værer alle ligesindede, medlidende, kjærlige mod Brødrene, barmhjertige, velvillige;"],[3,9,"betaler ikke Ondt med Ondt, eller Skjeldsord med Skjeldsord, men tvertimod velsigner, vidende, at I dertil ere kaldte, at I skulle arve Velsignelse.","betaler ikke Ondt med Ondt, eller Skjeldsord med Skjeldsord, men tvertimod velsigner, vidende, at I dertil ere kaldte, at I skulle arve Velsignelse."],[3,10,"Thi den, som vil elske Livet og see gode Dage, skal stille sin Tunge fra Ondt, og sine Læber, at de ikke tale Svig;","Thi den, som vil elske Livet og see gode Dage, skal stille sin Tunge fra Ondt, og sine Læber, at de ikke tale Svig;"],[3,11,"han vende sig fra ondt og gjøre Godt; han søge Fred og hige efter den.","han vende sig fra ondt og gjøre Godt; han søge Fred og hige efter den."],[3,12,"Thi Herrens Øine ere over de Retfærdige, og hans Øren til deres Bøn; men Herrens Ansigt er ogsaa over dem, som gjøre Ondt.","Thi Herrens Øine ere over de Retfærdige, og hans Øren til deres Bøn; men Herrens Ansigt er ogsaa over dem, som gjøre Ondt."],[3,13,"Og hvo er den, som kan skade Eder, dersom I beflitte Eder paa det Gode?","Og hvo er den, som kan skade Eder, dersom I beflitte Eder paa det Gode?"],[3,14,"Men om I og lide for Retfærdigheds Skyld, ere I salige. Men frygter ikke, som de frygte, og forfærdes ikke; men helliger Gud Herren i Eders Hjerter.","Men om I og lide for Retfærdigheds Skyld, ere I salige. Men frygter ikke, som de frygte, og forfærdes ikke; men helliger Gud Herren i Eders Hjerter."],[3,15,"Værer altid rede til at forsvare Eder med Sagtmodighed og Ærefrygt for enhver, som begjerer Regnskab af Eder om det Haab, som er i Eder,","Værer altid rede til at forsvare Eder med Sagtmodighed og Ærefrygt for enhver, som begjerer Regnskab af Eder om det Haab, som er i Eder,"],[3,16,"og haver en god Samvittighed, at de, der haane Eders gode Omgængelse i Christus, maae beskæmmes, idet de bagtale Eder som Misdædere.","og haver en god Samvittighed, at de, der haane Eders gode Omgængelse i Christus, maae beskæmmes, idet de bagtale Eder som Misdædere."],[3,17,"Thi det er bedre, (om det saa er Guds Villie), at lide, naar man gjør Godt, end naar man gjør Ondt.","Thi det er bedre, (om det saa er Guds Villie), at lide, naar man gjør Godt, end naar man gjør Ondt."],[3,18,"Thi og Christus led eengang for vore Synder, den Retfærdige for de Uretfærdige, at han kunde føre os frem til Gud, han, som vel led Døden efter Kjødet, men blev levendegjort efter Aanden;","Thi og Christus led eengang for vore Synder, den Retfærdige for de Uretfærdige, at han kunde føre os frem til Gud, han, som vel led Døden efter Kjødet, men blev levendegjort efter Aanden;"],[3,19,"i hvilken han og gik bort og prædikede for Aanderne, som vare i Forvaring,","i hvilken han og gik bort og prædikede for Aanderne, som vare i Forvaring,"],[3,20,"som fordum vare gjenstridige, der Guds Langmodighed ventede i Noe Dage, der Arken byggedes, i hvilken faa, nemlig otte, Sjæle bleve frelste i Vandet,","som fordum vare gjenstridige, der Guds Langmodighed ventede i Noe Dage, der Arken byggedes, i hvilken faa, nemlig otte, Sjæle bleve frelste i Vandet,"],[3,21,"hvis Modbillede nu frelser os, Daaben, hvilken ikke er Renselse fra Kjødets Ureenhed, men en god Samvittigheds Pagt med Gud ved Jesu Christi Opstandelse;","hvis Modbillede nu frelser os, Daaben, hvilken ikke er Renselse fra Kjødets Ureenhed, men en god Samvittigheds Pagt med Gud ved Jesu Christi Opstandelse;"],[3,22,"som, efterat han er faren til Himmelen, er hos Guds høire Haand, og Englene og Magterne og Kræfterne ere ham underlagte.","som, efterat han er faren til Himmelen, er hos Guds høire Haand, og Englene og Magterne og Kræfterne ere ham underlagte."],[4,1,"Efterdi da Christus var lidt for os i Kjødet, væbner Eder og med det samme Sind, (thi den, som haver lidt i Kjødet , haver ladet af fra Synden),","Efterdi da Christus var lidt for os i Kjødet, væbner Eder og med det samme Sind, (thi den, som haver lidt i Kjødet , haver ladet af fra Synden),"],[4,2,"saa at I skulle leve den øvrige Tid i Kjødet, ikke fremdeles efter menneskelige Lyster, men efter Guds Villie.","saa at I skulle leve den øvrige Tid i Kjødet, ikke fremdeles efter menneskelige Lyster, men efter Guds Villie."],[4,3,"Thi det er nok, at vi i den forbigangne Livs Tid have bedrevet Hedningernes Villie, vandrende i Uteerlighed, Lyster, Fylderi, Fraadseri, Drukkenskab og skjændig Afgudsdyrkelse;","Thi det er nok, at vi i den forbigangne Livs Tid have bedrevet Hedningernes Villie, vandrende i Uteerlighed, Lyster, Fylderi, Fraadseri, Drukkenskab og skjændig Afgudsdyrkelse;"],[4,4,"hvorover de forundre sig, da I ikke løbe med til den samme Ryggesløsheds Dynd, og de bespotte Eder;","hvorover de forundre sig, da I ikke løbe med til den samme Ryggesløsheds Dynd, og de bespotte Eder;"],[4,5,"men de skulle gjøre ham Regnskab, som er rede til at dømme Levende og Døde.","men de skulle gjøre ham Regnskab, som er rede til at dømme Levende og Døde."],[4,6,"Thi derfor er Evangelium forkyndt for de Døde, at de vel skulle dømmes for Mennesker i Kjødet, men leve for Gud i Aanden.","Thi derfor er Evangelium forkyndt for de Døde, at de vel skulle dømmes for Mennesker i Kjødet, men leve for Gud i Aanden."],[4,7,"Men alle Tings Ende nærmer sig; værer derfor ædrue og aarvaagne til Bønnen.","Men alle Tings Ende nærmer sig; værer derfor ædrue og aarvaagne til Bønnen."],[4,8,"Men haver for alle Ting en inderlig Kjærlighed til hverandre; thi Kjærligheden skal skjule Synders Mangfoldighed.","Men haver for alle Ting en inderlig Kjærlighed til hverandre; thi Kjærligheden skal skjule Synders Mangfoldighed."],[4,9,"Laaner hverandre gjerne Huus uden Knur.","Laaner hverandre gjerne Huus uden Knur."],[4,10,"Som enhver haver faaet en Naadegave, saa tjener hverandre dermed, som gode Huusholdere over Guds mangeslags Naade.","Som enhver haver faaet en Naadegave, saa tjener hverandre dermed, som gode Huusholdere over Guds mangeslags Naade."],[4,11,"Taler Nogen i Menigheden, han tale som Guds Ord; tjener Nogen deri, han tjene som af den Formue, hvilken Gud forlener, at Gud maa æres i alle Ting formedelst Jesus Christus; ham tilkommer Ære og Magt i al Evighed! Amen.","Taler Nogen i Menigheden, han tale som Guds Ord; tjener Nogen deri, han tjene som af den Formue, hvilken Gud forlener, at Gud maa æres i alle Ting formedelst Jesus Christus; ham tilkommer Ære og Magt i al Evighed! Amen."],[4,12,"I Elskelige! forundrer Eder ikke over den Ildprøve, som I gjennemgaae, Eder til en Forsøgelse, som om der hændtes Eder noget Underligt,","I Elskelige! forundrer Eder ikke over den Ildprøve, som I gjennemgaae, Eder til en Forsøgelse, som om der hændtes Eder noget Underligt,"],[4,13,"men som I ere deelagtige i Christi Lidelser, saa glæder Eder, at I og ved hans Herligheds Aabenbarelse skulle glæde og fryde Eder.","men som I ere deelagtige i Christi Lidelser, saa glæder Eder, at I og ved hans Herligheds Aabenbarelse skulle glæde og fryde Eder."],[4,14,"Dersom I forhaanes for Christi Navns Skyld, ere I salige, thi Herlighedens og Guds Aand hviler paa Eder; hos hine bespottes den vel, men hos Eder herliggjøres den.","Dersom I forhaanes for Christi Navns Skyld, ere I salige, thi Herlighedens og Guds Aand hviler paa Eder; hos hine bespottes den vel, men hos Eder herliggjøres den."],[4,15,"Thi Ingen af Eder lide som Morder eller Tyv eller Misdæder, eller som den, der trænger sig ind i en fremmed Bestilling;","Thi Ingen af Eder lide som Morder eller Tyv eller Misdæder, eller som den, der trænger sig ind i en fremmed Bestilling;"],[4,16,"men lider han som en Christen, da skamme han sig ikke, men ære Gud i den Deel.","men lider han som en Christen, da skamme han sig ikke, men ære Gud i den Deel."],[4,17,"Thi det er Tiden, at Dommen skal begynde fra Guds Huus; men begynder den først fra os, hvad Ende vil det faae med den, som ikke troe Guds Evangelium?","Thi det er Tiden, at Dommen skal begynde fra Guds Huus; men begynder den først fra os, hvad Ende vil det faae med den, som ikke troe Guds Evangelium?"],[4,18,"Og dersom den Retfærdige neppeligen frelses, hvor vil den Ugudelige og Synderen komme frem?","Og dersom den Retfærdige neppeligen frelses, hvor vil den Ugudelige og Synderen komme frem?"],[4,19,"Derfor skulle og de, som lide efter Guds Villie, befale ham, som en trofast Skaber, deres Sjæle ved at gjøre Godt.","Derfor skulle og de, som lide efter Guds Villie, befale ham, som en trofast Skaber, deres Sjæle ved at gjøre Godt."],[5,1,"De Ældste iblandt Eder formaner jeg som en Med-Ældste og Vidne til Christi Lidelser, som den, der og har Deel i Herligheden, der skal aabenbares:","De Ældste iblandt Eder formaner jeg som en Med-Ældste og Vidne til Christi Lidelser, som den, der og har Deel i Herligheden, der skal aabenbares:"],[5,2,"vogter Guds Hjord, som er iblandt Eder, og vaager over den, ikke tvungne, men frivillig, ikke for slet Vindings Skyld, men med Redebonhed;","vogter Guds Hjord, som er iblandt Eder, og vaager over den, ikke tvungne, men frivillig, ikke for slet Vindings Skyld, men med Redebonhed;"],[5,3,"ikke som de, der ville herske over Herrens Arv, men som Mønstre for Hjorden.","ikke som de, der ville herske over Herrens Arv, men som Mønstre for Hjorden."],[5,4,"Og naar da Overhyrden aabenbares, skulle I erholde Ærens uforvisnelige Krands.","Og naar da Overhyrden aabenbares, skulle I erholde Ærens uforvisnelige Krands."],[5,5,"Desligeste, I Unge: værer de Ældste underdanige og smykker Eder med Ydmyghed; thi Gud staaer de Hoffærdige imod, men de Ydmyge giver han Naade.","Desligeste, I Unge: værer de Ældste underdanige og smykker Eder med Ydmyghed; thi Gud staaer de Hoffærdige imod, men de Ydmyge giver han Naade."],[5,6,"Derfor ydmyger Eder under Guds Vældige Haand, at han maa i sin Tid ophøie Eder.","Derfor ydmyger Eder under Guds Vældige Haand, at han maa i sin Tid ophøie Eder."],[5,7,"Kaster al Eders Sorg paa ham, thi han haver Omhu for Eder.","Kaster al Eders Sorg paa ham, thi han haver Omhu for Eder."],[5,8,"Værer ædrue, vaager; thi Eders Modstander, Djævelen, gaaer omkring som en brølende Løve, søgende, hvem han kan opsluge.","Værer ædrue, vaager; thi Eders Modstander, Djævelen, gaaer omkring som en brølende Løve, søgende, hvem han kan opsluge."],[5,9,"Staaer ham imod, faste i Troen, vidende, at de samme Lidelser fuldbyrdes paa Eders Brødre i Verden.","Staaer ham imod, faste i Troen, vidende, at de samme Lidelser fuldbyrdes paa Eders Brødre i Verden."],[5,10,"Men al Naades Gud, som kaldte os til sin evige Herlighed i Christus Jesus, efter en kort Tids Lidelse, han selv berede, styrke, bekræfte, grundfæste Eder!","Men al Naades Gud, som kaldte os til sin evige Herlighed i Christus Jesus, efter en kort Tids Lidelse, han selv berede, styrke, bekræfte, grundfæste Eder!"],[5,11,"Ham være Ære og Magt i al Evighed! Amen.","Ham være Ære og Magt i al Evighed! Amen."],[5,12,"Med Silvanus, den trofaste Broder, (thi det holder jeg ham for), haver jeg i Korthed skrevet Eder til og formaner og vidner, at denne er Guds sande Naade, i hvilken I staae.","Med Silvanus, den trofaste Broder, (thi det holder jeg ham for), haver jeg i Korthed skrevet Eder til og formaner og vidner, at denne er Guds sande Naade, i hvilken I staae."],[5,13,"Den medudvalgte Menighed i Babylon hilser Eder, saa og Marcus, min Søn.","Den medudvalgte Menighed i Babylon hilser Eder, saa og Marcus, min Søn."],[5,14,"Hilser hverandre med Kjærligheds Kys. Fred være med Eder alle, som ere i Christus Jesus! Amen.","Hilser hverandre med Kjærligheds Kys. Fred være med Eder alle, som ere i Christus Jesus! Amen."]],"epo-londona":[[1,1,"Petro, apostolo de Jesuo Kristo, al la elektitoj, kiuj estas el la dispelitaro, pasloĝantaj en Ponto, Galatujo, Kapadokio, Azio, kaj Bitinio,","Petro, apostolo de Jesuo Kristo, al la elektitoj, kiuj estas el la dispelitaro, pasloĝantaj en Ponto, Galatujo, Kapadokio, Azio, kaj Bitinio,"],[1,2,"laŭ la antaŭscio de Dio, la Patro, en sanktigo de la Spirito, por obeo kaj aspergo de la sango de Jesuo Kristo: Graco al vi kaj paco pligrandiĝu.","laŭ la antaŭscio de Dio, la Patro, en sanktigo de la Spirito, por obeo kaj aspergo de la sango de Jesuo Kristo: Graco al vi kaj paco pligrandiĝu."],[1,3,"Benata estu la Dio kaj Patro de nia Sinjoro Jesuo Kristo, kiu laŭ Sia granda kompato nin renaskis en esperon vivan per la releviĝo de Jesuo Kristo el la mortintoj,","Benata estu la Dio kaj Patro de nia Sinjoro Jesuo Kristo, kiu laŭ Sia granda kompato nin renaskis en esperon vivan per la releviĝo de Jesuo Kristo el la mortintoj,"],[1,4,"en heredaĵon ne pereontan, ne makulotan, ne velkontan, rezervitan en la ĉielo por vi,","en heredaĵon ne pereontan, ne makulotan, ne velkontan, rezervitan en la ĉielo por vi,"],[1,5,"kiuj estas gardataj de la potenco de Dio per fido al savo preta malkaŝiĝi en la lasta tempo.","kiuj estas gardataj de la potenco de Dio per fido al savo preta malkaŝiĝi en la lasta tempo."],[1,6,"En tio vi ĝojegas, kvankam por kelka tempo, se estas necese, malĝojigite en diversaj tentoj,","En tio vi ĝojegas, kvankam por kelka tempo, se estas necese, malĝojigite en diversaj tentoj,"],[1,7,"por ke la provado de via fido, pli multevalora ol oro, kiu pereas, kvankam per fajro provite, troviĝu efika por laŭdo kaj gloro kaj honoro en la malkaŝo de Jesuo Kristo;","por ke la provado de via fido, pli multevalora ol oro, kiu pereas, kvankam per fajro provite, troviĝu efika por laŭdo kaj gloro kaj honoro en la malkaŝo de Jesuo Kristo;"],[1,8,"kiun, ne vidinte, vi amas; kiun kvankam nun vi ne vidas, tamen, al li kredante, vi ĝojegas per ĝojo nedirebla kaj gloroplena;","kiun, ne vidinte, vi amas; kiun kvankam nun vi ne vidas, tamen, al li kredante, vi ĝojegas per ĝojo nedirebla kaj gloroplena;"],[1,9,"ricevante la celon de via fido, savon de animoj.","ricevante la celon de via fido, savon de animoj."],[1,10,"Koncerne tiun savon esploris kaj serĉis la profetoj, kiuj profetis pri la graco venonta al vi;","Koncerne tiun savon esploris kaj serĉis la profetoj, kiuj profetis pri la graco venonta al vi;"],[1,11,"serĉante, kiun kaj kian tempon montris la enestanta en ili Spirito de Kristo, kiu atestis antaŭe la suferojn por Kristo kaj la sekvontajn glorojn.","serĉante, kiun kaj kian tempon montris la enestanta en ili Spirito de Kristo, kiu atestis antaŭe la suferojn por Kristo kaj la sekvontajn glorojn."],[1,12,"Kaj al ili malkaŝiĝis, ke ne al si mem, sed al vi, ili liveris tion, kio nun estas proklamita al vi de tiuj, kiuj predikis al vi la evangelion per la Spirito Sankta, elsendita el la ĉielo; en kiujn aferojn anĝeloj deziras enrigardi.","Kaj al ili malkaŝiĝis, ke ne al si mem, sed al vi, ili liveris tion, kio nun estas proklamita al vi de tiuj, kiuj predikis al vi la evangelion per la Spirito Sankta, elsendita el la ĉielo; en kiujn aferojn anĝeloj deziras enrigardi."],[1,13,"Tial, ĉirkaŭzoninte la lumbojn de via menso, estu sobraj kaj esperadu perfekte la gracon alportotan al vi en la malkaŝo de Jesuo Kristo;","Tial, ĉirkaŭzoninte la lumbojn de via menso, estu sobraj kaj esperadu perfekte la gracon alportotan al vi en la malkaŝo de Jesuo Kristo;"],[1,14,"kiel infanoj de obeo, ne formiĝante laŭ la voluptoj, kiujn vi antaŭe havis en via nescio;","kiel infanoj de obeo, ne formiĝante laŭ la voluptoj, kiujn vi antaŭe havis en via nescio;"],[1,15,"sed kiel via Vokinto estas sankta, tiel vi ankaŭ fariĝu sanktaj en ĉia konduto;","sed kiel via Vokinto estas sankta, tiel vi ankaŭ fariĝu sanktaj en ĉia konduto;"],[1,16,"pro tio, ke estas skribite: Vi estu sanktaj, ĉar Mi estas sankta.","pro tio, ke estas skribite: Vi estu sanktaj, ĉar Mi estas sankta."],[1,17,"Kaj se vi vokas la Patron, kiu sen personfavorado juĝas laŭ la faro de ĉiu, vi pasigu en timo la tempon de via ĉi tiea loĝado;","Kaj se vi vokas la Patron, kiu sen personfavorado juĝas laŭ la faro de ĉiu, vi pasigu en timo la tempon de via ĉi tiea loĝado;"],[1,18,"sciante, ke ne per pereemaj objektoj, oro aŭ arĝento, vi elaĉetiĝis el via vanta vivmaniero, kiun vi ricevis de viaj patroj;","sciante, ke ne per pereemaj objektoj, oro aŭ arĝento, vi elaĉetiĝis el via vanta vivmaniero, kiun vi ricevis de viaj patroj;"],[1,19,"sed per multekosta sango, kiel de ŝafido senmakula kaj sendifekta, la sango de Kristo;","sed per multekosta sango, kiel de ŝafido senmakula kaj sendifekta, la sango de Kristo;"],[1,20,"kiu estis antaŭdifinita antaŭ la fondo de la mondo, sed elmontrita en la fino de la tempoj pro vi,","kiu estis antaŭdifinita antaŭ la fondo de la mondo, sed elmontrita en la fino de la tempoj pro vi,"],[1,21,"kiuj per li fidas Dion, kiu relevis lin el la mortintoj kaj donis al li gloron; por ke via fido kaj espero estu al Dio.","kiuj per li fidas Dion, kiu relevis lin el la mortintoj kaj donis al li gloron; por ke via fido kaj espero estu al Dio."],[1,22,"Ĉastiginte viajn animojn, en la obeo al la vero, por sincera amo al la frataro, amu unu la alian el la koro fervore;","Ĉastiginte viajn animojn, en la obeo al la vero, por sincera amo al la frataro, amu unu la alian el la koro fervore;"],[1,23,"renaskite, ne el pereema semo, sed el nepereema, per la vorto de Dio, vivanta kaj restanta.","renaskite, ne el pereema semo, sed el nepereema, per la vorto de Dio, vivanta kaj restanta."],[1,24,"Ĉar: Ĉiu karno estas herbo, Kaj ĉiu ĝia ĉarmo estas kiel kampa floreto. Sekiĝas herbo, velkas floreto;","Ĉar: Ĉiu karno estas herbo, Kaj ĉiu ĝia ĉarmo estas kiel kampa floreto. Sekiĝas herbo, velkas floreto;"],[1,25,"Sed la vorto de la Eternulo restas eterne. Kaj ĉi tiu estas la parolo, kiu estas predikita al vi.","Sed la vorto de la Eternulo restas eterne. Kaj ĉi tiu estas la parolo, kiu estas predikita al vi."],[2,1,"Formetinte do ĉian malbonon kaj ĉian trompon kaj hipokritecon kaj enviojn kaj ĉiajn kalumniojn,","Formetinte do ĉian malbonon kaj ĉian trompon kaj hipokritecon kaj enviojn kaj ĉiajn kalumniojn,"],[2,2,"kiel ĵusnaskitaj suĉinfanoj, sopiru al la spirita lakto pura, por ke vi per tio kresku en savon,","kiel ĵusnaskitaj suĉinfanoj, sopiru al la spirita lakto pura, por ke vi per tio kresku en savon,"],[2,3,"se vi gustumis, ke la Sinjoro estas bona;","se vi gustumis, ke la Sinjoro estas bona;"],[2,4,"al kiu alvenante, kvazaŭ al ŝtono vivanta, de homoj rifuzita, sed ĉe Dio elektita, honorinda,","al kiu alvenante, kvazaŭ al ŝtono vivanta, de homoj rifuzita, sed ĉe Dio elektita, honorinda,"],[2,5,"vi ankaŭ, kiel ŝtonoj vivantaj, konstruiĝas domo spirita, sankta pastraro, por oferi spiritajn oferojn, akcepteblajn de Dio per Jesuo Kristo.","vi ankaŭ, kiel ŝtonoj vivantaj, konstruiĝas domo spirita, sankta pastraro, por oferi spiritajn oferojn, akcepteblajn de Dio per Jesuo Kristo."],[2,6,"Ĉar estas enhavate en skribo: Jen Mi kuŝigas en Cion bazangulan ŝtonon, elektitan, valoregan; Kaj kiu lin fidas, tiu ne estos hontigita.","Ĉar estas enhavate en skribo: Jen Mi kuŝigas en Cion bazangulan ŝtonon, elektitan, valoregan; Kaj kiu lin fidas, tiu ne estos hontigita."],[2,7,"Por vi do, la fidantoj, estas la valoregeco; sed por nefidantoj: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula;","Por vi do, la fidantoj, estas la valoregeco; sed por nefidantoj: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula;"],[2,8,"kaj: Ŝtono de falpuŝiĝo kaj roko de alfrapiĝo; ili falpuŝiĝas pro la vorto, malobeante, por kio ankaŭ ili estas difinitaj.","kaj: Ŝtono de falpuŝiĝo kaj roko de alfrapiĝo; ili falpuŝiĝas pro la vorto, malobeante, por kio ankaŭ ili estas difinitaj."],[2,9,"Sed vi estas raso elektita, pastraro reĝa, nacio sankta, popolo Diposedata, por ke vi proklamu la gloron de Tiu, kiu vokis vin el mallumo en Sian lumon mirindan;","Sed vi estas raso elektita, pastraro reĝa, nacio sankta, popolo Diposedata, por ke vi proklamu la gloron de Tiu, kiu vokis vin el mallumo en Sian lumon mirindan;"],[2,10,"kiuj iam estis ne-popolo, sed nun estas popolo de Dio; antaŭe nekompatitoj, sed nun kompatitoj.","kiuj iam estis ne-popolo, sed nun estas popolo de Dio; antaŭe nekompatitoj, sed nun kompatitoj."],[2,11,"Amataj, mi petegas vin kiel fremdulojn kaj migrantojn, detenu vin de karnaj voluptoj, kiuj militadas kontraŭ la animo;","Amataj, mi petegas vin kiel fremdulojn kaj migrantojn, detenu vin de karnaj voluptoj, kiuj militadas kontraŭ la animo;"],[2,12,"kondutante dece ĉe la nacianoj, por ke, kvankam ili kalumnias vin kiel malbonagulojn, tamen, vidante viajn bonfarojn, ili gloru Dion en la tago de vizitado.","kondutante dece ĉe la nacianoj, por ke, kvankam ili kalumnias vin kiel malbonagulojn, tamen, vidante viajn bonfarojn, ili gloru Dion en la tago de vizitado."],[2,13,"Submetu vin al ĉiu homa institucio pro la Sinjoro; ĉu al la reĝo, la superreganto;","Submetu vin al ĉiu homa institucio pro la Sinjoro; ĉu al la reĝo, la superreganto;"],[2,14,"ĉu al regantoj, kiel liaj senditoj por venĝo al malbonaguloj kaj por laŭdo al bonaguloj.","ĉu al regantoj, kiel liaj senditoj por venĝo al malbonaguloj kaj por laŭdo al bonaguloj."],[2,15,"Ĉar la volo de Dio estas, ke bonfarante, vi silentigu la nesciadon de homoj malsaĝaj;","Ĉar la volo de Dio estas, ke bonfarante, vi silentigu la nesciadon de homoj malsaĝaj;"],[2,16,"kiel liberaj, kaj ne farantaj el via libereco kovrilon de malico, sed kiel servistoj de Dio.","kiel liberaj, kaj ne farantaj el via libereco kovrilon de malico, sed kiel servistoj de Dio."],[2,17,"Ĉiujn honoru. La frataron amu. Dion timu. La reĝon honoru.","Ĉiujn honoru. La frataron amu. Dion timu. La reĝon honoru."],[2,18,"Servantoj, submetu vin al viaj sinjoroj kun ĉia timo; ne sole al la bonaj kaj malseveraj, sed ankaŭ al la malbonhumoraj.","Servantoj, submetu vin al viaj sinjoroj kun ĉia timo; ne sole al la bonaj kaj malseveraj, sed ankaŭ al la malbonhumoraj."],[2,19,"Ĉar tio estas laŭdinda, se pro konscienco al Dio oni elportas malĝojon, suferante maljuste.","Ĉar tio estas laŭdinda, se pro konscienco al Dio oni elportas malĝojon, suferante maljuste."],[2,20,"Ĉar kia honoro estas, se, pekante kaj sekve batate, vi tion pacience elportas? sed se, bonfarante kaj sekve suferante, vi tion pacience elportas, tio estas laŭdinda antaŭ Dio.","Ĉar kia honoro estas, se, pekante kaj sekve batate, vi tion pacience elportas? sed se, bonfarante kaj sekve suferante, vi tion pacience elportas, tio estas laŭdinda antaŭ Dio."],[2,21,"Ĉar al ĉi tio vi estas vokitaj; pro tio, ke Kristo ankaŭ suferis pro vi, postlasante por vi ekzemplon, por ke vi sekvu liajn postesignojn;","Ĉar al ĉi tio vi estas vokitaj; pro tio, ke Kristo ankaŭ suferis pro vi, postlasante por vi ekzemplon, por ke vi sekvu liajn postesignojn;"],[2,22,"pekon li ne faris, kaj trompo ne troviĝis en lia buŝo;","pekon li ne faris, kaj trompo ne troviĝis en lia buŝo;"],[2,23,"insultate, li ne insultis responde; suferante, li ne minacis, sed submetis sin al la juste juĝanta;","insultate, li ne insultis responde; suferante, li ne minacis, sed submetis sin al la juste juĝanta;"],[2,24,"li mem portis niajn pekojn en sia korpo sur la lignaĵo, por ke ni, malvivigite koncerne pekojn, vivu por justeco; per lia vundo vi resaniĝis.","li mem portis niajn pekojn en sia korpo sur la lignaĵo, por ke ni, malvivigite koncerne pekojn, vivu por justeco; per lia vundo vi resaniĝis."],[2,25,"Ĉar vi estis kiel ŝafoj erarvagantaj; sed nun vi returne venis al la Paŝtisto kaj Episkopo de viaj animoj.","Ĉar vi estis kiel ŝafoj erarvagantaj; sed nun vi returne venis al la Paŝtisto kaj Episkopo de viaj animoj."],[3,1,"Tiel same, edzinoj, submetu vin al viaj propraj edzoj; por ke, eĉ se iuj ne obeas al la vorto, ili sen la vorto estu gajnitaj per la konduto de siaj edzinoj,","Tiel same, edzinoj, submetu vin al viaj propraj edzoj; por ke, eĉ se iuj ne obeas al la vorto, ili sen la vorto estu gajnitaj per la konduto de siaj edzinoj,"],[3,2,"rigardante vian konduton kun timo ĉastan.","rigardante vian konduton kun timo ĉastan."],[3,3,"Via ornamo estu ne la ekstera ornamo de harplektado kaj orportado, aŭ la surmetado de vestoj;","Via ornamo estu ne la ekstera ornamo de harplektado kaj orportado, aŭ la surmetado de vestoj;"],[3,4,"sed la kaŝita homo de la koro en la nedifektebla vesto de spirito milda kaj trankvila, kiu estas multevalora antaŭ Dio.","sed la kaŝita homo de la koro en la nedifektebla vesto de spirito milda kaj trankvila, kiu estas multevalora antaŭ Dio."],[3,5,"Ĉar tiel same ankaŭ, en la tempo antikva, la sanktaj virinoj, kiuj esperis al Dio, ornamis sin, submetante sin al siaj propraj edzoj;","Ĉar tiel same ankaŭ, en la tempo antikva, la sanktaj virinoj, kiuj esperis al Dio, ornamis sin, submetante sin al siaj propraj edzoj;"],[3,6,"kiel Sara obeis al Abraham, nomante lin sinjoro; kies infanoj vi fariĝis, bonfarante, kaj ne ektimigate per ia teruro.","kiel Sara obeis al Abraham, nomante lin sinjoro; kies infanoj vi fariĝis, bonfarante, kaj ne ektimigate per ia teruro."],[3,7,"Tiel same, edzoj, kunvivadu kun viaj edzinoj laŭscie, donante honoron al la virino kiel al la plimalforta ilo, kaj estante ankaŭ kun ili kunheredantoj de la graco de vivo, por ke viaj preĝoj ne malhelpiĝu.","Tiel same, edzoj, kunvivadu kun viaj edzinoj laŭscie, donante honoron al la virino kiel al la plimalforta ilo, kaj estante ankaŭ kun ili kunheredantoj de la graco de vivo, por ke viaj preĝoj ne malhelpiĝu."],[3,8,"Fine, estu ĉiuj samideaj, simpatiaj, fratamemaj, kompatemaj, humilanimaj;","Fine, estu ĉiuj samideaj, simpatiaj, fratamemaj, kompatemaj, humilanimaj;"],[3,9,"ne repagantaj malbonon kontraŭ malbono, nek insulton kontraŭ insulto, sed kontraŭe benadantaj; ĉar al tio vi estas vokitaj, por ke vi heredu benon.","ne repagantaj malbonon kontraŭ malbono, nek insulton kontraŭ insulto, sed kontraŭe benadantaj; ĉar al tio vi estas vokitaj, por ke vi heredu benon."],[3,10,"Ĉar: Kiu volas ami vivon kaj vidi bonajn tagojn, Tiu gardu sian langon kontraŭ malbono, Kaj sian buŝon kontraŭ mensoga parolo;","Ĉar: Kiu volas ami vivon kaj vidi bonajn tagojn, Tiu gardu sian langon kontraŭ malbono, Kaj sian buŝon kontraŭ mensoga parolo;"],[3,11,"Li dekliniĝu de malbono kaj faru bonon, Li serĉu pacon, kaj ĉasu ĝin.","Li dekliniĝu de malbono kaj faru bonon, Li serĉu pacon, kaj ĉasu ĝin."],[3,12,"Ĉar la okuloj de la Eternulo estas turnitaj al la piuloj, Kaj Liaj oreloj al iliaj krioj; Sed la vizaĝo de la Eternulo estas kontraŭ tiuj, kiuj faras malbonon.","Ĉar la okuloj de la Eternulo estas turnitaj al la piuloj, Kaj Liaj oreloj al iliaj krioj; Sed la vizaĝo de la Eternulo estas kontraŭ tiuj, kiuj faras malbonon."],[3,13,"Kaj kiu faros al vi malbonon, se vi fariĝos fervoraj en la bono?","Kaj kiu faros al vi malbonon, se vi fariĝos fervoraj en la bono?"],[3,14,"Sed se vi eĉ suferus pro justeco, feliĉegaj vi estus; kaj ilian timon ne timu, nek maltrankviliĝu;","Sed se vi eĉ suferus pro justeco, feliĉegaj vi estus; kaj ilian timon ne timu, nek maltrankviliĝu;"],[3,15,"sed la Sinjoron Kriston sanktigu en viaj koroj; estu ĉiam pretaj doni defendan respondon al ĉiu, kiu vin demandas pri la motivo de la espero en vi, sed kun humileco kaj timo;","sed la Sinjoron Kriston sanktigu en viaj koroj; estu ĉiam pretaj doni defendan respondon al ĉiu, kiu vin demandas pri la motivo de la espero en vi, sed kun humileco kaj timo;"],[3,16,"havantaj bonan konsciencon; por ke, dum vi estas malestimataj, hontu tiuj, kiuj kalumnias vian bonan konduton en Kristo.","havantaj bonan konsciencon; por ke, dum vi estas malestimataj, hontu tiuj, kiuj kalumnias vian bonan konduton en Kristo."],[3,17,"Ĉar pli bone estus, se tiel volus Dio, suferi pro bonfarado, ol pro malbonfarado.","Ĉar pli bone estus, se tiel volus Dio, suferi pro bonfarado, ol pro malbonfarado."],[3,18,"Ĉar Kristo ankaŭ unufoje suferis pro pekoj, justulo pro maljustuloj, por ke li nin konduku al Dio; mortigite en la karno, sed vivigite en la spirito;","Ĉar Kristo ankaŭ unufoje suferis pro pekoj, justulo pro maljustuloj, por ke li nin konduku al Dio; mortigite en la karno, sed vivigite en la spirito;"],[3,19,"en kiu ankaŭ li iris kaj predikis al la enkarceraj spiritoj,","en kiu ankaŭ li iris kaj predikis al la enkarceraj spiritoj,"],[3,20,"kiuj iam malobeis, kiam la longedaŭra pacienco de Dio atendis en la tagoj de Noa dum la pretigado de la arkeo, en kiu malmultaj, tio estas ok personoj, elsaviĝis tra akvo;","kiuj iam malobeis, kiam la longedaŭra pacienco de Dio atendis en la tagoj de Noa dum la pretigado de la arkeo, en kiu malmultaj, tio estas ok personoj, elsaviĝis tra akvo;"],[3,21,"kiu ankaŭ vin nun savas en antitipo, la bapto, ne la formetado de la karna malpuraĵo, sed la demando de bona konscienco al Dio per la releviĝo de Jesuo Kristo;","kiu ankaŭ vin nun savas en antitipo, la bapto, ne la formetado de la karna malpuraĵo, sed la demando de bona konscienco al Dio per la releviĝo de Jesuo Kristo;"],[3,22,"kiu estas dekstre de Dio, irinte en la ĉielon; al li anĝeloj kaj aŭtoritatoj kaj potencoj estas submetitaj.","kiu estas dekstre de Dio, irinte en la ĉielon; al li anĝeloj kaj aŭtoritatoj kaj potencoj estas submetitaj."],[4,1,"Ĉar Kristo do suferis en la karno, vi ankaŭ armu vin per la sama intenco; ĉar la suferinto en la karno apartiĝis de pekoj;","Ĉar Kristo do suferis en la karno, vi ankaŭ armu vin per la sama intenco; ĉar la suferinto en la karno apartiĝis de pekoj;"],[4,2,"por ke vi travivu la reston de la enkarna tempo jam ne laŭ la voluptoj de homoj, sed laŭ la volo de Dio.","por ke vi travivu la reston de la enkarna tempo jam ne laŭ la voluptoj de homoj, sed laŭ la volo de Dio."],[4,3,"Ĉar la tempo pasinta sufiĉas, por elfari la deziron de la nacianoj kaj iradi en diboĉoj, voluptoj, vindrinkado, brufestenoj, ebrieco, kaj abomenaj idolkultoj;","Ĉar la tempo pasinta sufiĉas, por elfari la deziron de la nacianoj kaj iradi en diboĉoj, voluptoj, vindrinkado, brufestenoj, ebrieco, kaj abomenaj idolkultoj;"],[4,4,"en kio ili miras, ke vi ne kuras kune kun ili en la saman superfluon de diboĉado, kaj ili kalumnias vin;","en kio ili miras, ke vi ne kuras kune kun ili en la saman superfluon de diboĉado, kaj ili kalumnias vin;"],[4,5,"ili prirespondos al Tiu, kiu estas preta juĝi la vivantojn kaj la mortintojn.","ili prirespondos al Tiu, kiu estas preta juĝi la vivantojn kaj la mortintojn."],[4,6,"Ĉar por tio ankaŭ la evangelio estas anoncita al la mortintoj, por ke ili estu korpe juĝitaj laŭ homoj, sed spirite vivu laŭ Dio.","Ĉar por tio ankaŭ la evangelio estas anoncita al la mortintoj, por ke ili estu korpe juĝitaj laŭ homoj, sed spirite vivu laŭ Dio."],[4,7,"Sed la fino de ĉio alproksimiĝas; prudentiĝu do, kaj sobriĝu por preĝoj;","Sed la fino de ĉio alproksimiĝas; prudentiĝu do, kaj sobriĝu por preĝoj;"],[4,8,"antaŭ ĉio havante fervoran amon unu al alia; ĉar amo kovras amason da pekoj;","antaŭ ĉio havante fervoran amon unu al alia; ĉar amo kovras amason da pekoj;"],[4,9,"estu gastamaj unu al alia sen murmurado;","estu gastamaj unu al alia sen murmurado;"],[4,10,"laŭmezure, kiel ĉiu ricevis donacon, tiel ĝin administrante inter vi, kiel bonaj administrantoj de la diversaspeca graco de Dio;","laŭmezure, kiel ĉiu ricevis donacon, tiel ĝin administrante inter vi, kiel bonaj administrantoj de la diversaspeca graco de Dio;"],[4,11,"se iu parolas, li parolu kvazaŭ orakolojn de Dio; se iu administras, li administru kvazaŭ el la forto, kiun Dio provizas; por ke en ĉio Dio estu glorata per Jesuo Kristo, kies estas la gloro kaj la potenco por ĉiam kaj eterne. Amen.","se iu parolas, li parolu kvazaŭ orakolojn de Dio; se iu administras, li administru kvazaŭ el la forto, kiun Dio provizas; por ke en ĉio Dio estu glorata per Jesuo Kristo, kies estas la gloro kaj la potenco por ĉiam kaj eterne. Amen."],[4,12,"Amataj, ne surpriziĝu pri la fajrego ĉe vi okazanta por provi vin, kvazaŭ io stranga okazus ĉe vi;","Amataj, ne surpriziĝu pri la fajrego ĉe vi okazanta por provi vin, kvazaŭ io stranga okazus ĉe vi;"],[4,13,"sed laŭ tio, ke vi partoprenas en la suferoj de Kristo, ĝoju; por ke ankaŭ en la elmontro de lia gloro vi ĝoju ravege.","sed laŭ tio, ke vi partoprenas en la suferoj de Kristo, ĝoju; por ke ankaŭ en la elmontro de lia gloro vi ĝoju ravege."],[4,14,"Se vi estas riproĉataj pro la nomo de Kristo, feliĉegaj vi estas; ĉar la Spirito de gloro kaj la Spirito de Dio restas sur vi.","Se vi estas riproĉataj pro la nomo de Kristo, feliĉegaj vi estas; ĉar la Spirito de gloro kaj la Spirito de Dio restas sur vi."],[4,15,"Nur neniu el vi suferu kiel mortiginto, aŭ ŝtelisto, aŭ malbonfarinto, aŭ kiel sintrudanto en malpropraj aferoj;","Nur neniu el vi suferu kiel mortiginto, aŭ ŝtelisto, aŭ malbonfarinto, aŭ kiel sintrudanto en malpropraj aferoj;"],[4,16,"sed se iu suferas kiel Kristano, li ne hontu; sed li gloru Dion en tiu nomo.","sed se iu suferas kiel Kristano, li ne hontu; sed li gloru Dion en tiu nomo."],[4,17,"Ĉar jam venis la tempo por la komenco de la juĝo ĉe la domo de Dio; kaj se ĝi komenciĝas ĉe ni, kia estos la sorto de tiuj, kiuj ne obeas al la evangelio de Dio?","Ĉar jam venis la tempo por la komenco de la juĝo ĉe la domo de Dio; kaj se ĝi komenciĝas ĉe ni, kia estos la sorto de tiuj, kiuj ne obeas al la evangelio de Dio?"],[4,18,"Kaj se justulo apenaŭ saviĝas, kie aperos malpiulo kaj pekulo?","Kaj se justulo apenaŭ saviĝas, kie aperos malpiulo kaj pekulo?"],[4,19,"Tial ankaŭ tiuj, kiuj suferas laŭ la volo de Dio, alkonfidu siajn animojn en bonfarado al fidela Kreinto.","Tial ankaŭ tiuj, kiuj suferas laŭ la volo de Dio, alkonfidu siajn animojn en bonfarado al fidela Kreinto."],[5,1,"La presbiterojn do inter vi mi admonas, estante kunpresbitero kaj atestanto de la suferoj de Kristo kaj partoprenanto en la malkaŝota gloro:","La presbiterojn do inter vi mi admonas, estante kunpresbitero kaj atestanto de la suferoj de Kristo kaj partoprenanto en la malkaŝota gloro:"],[5,2,"Paŝtu la gregon de Dio ĉe vi, direktante ĝin, ne devige, sed volonte, laŭ Dio; ne pro avideco, sed bonvole;","Paŝtu la gregon de Dio ĉe vi, direktante ĝin, ne devige, sed volonte, laŭ Dio; ne pro avideco, sed bonvole;"],[5,3,"ne kvazaŭ sinjorante super la heredo, sed fariĝante ekzemploj al la grego.","ne kvazaŭ sinjorante super la heredo, sed fariĝante ekzemploj al la grego."],[5,4,"Kaj kiam elmontriĝos la Ĉefpaŝtisto, vi ricevos la nevelkontan kronon de gloro.","Kaj kiam elmontriĝos la Ĉefpaŝtisto, vi ricevos la nevelkontan kronon de gloro."],[5,5,"Tiel same, vi plijunuloj, submetu vin al la pliaĝuloj. Tial ankaŭ vi ĉiuj submetu vin unu al la alia, kaj zonu vin per humileco; ĉar Dio kontraŭstaras al la fieruloj, sed al la humiluloj donas gracon.","Tiel same, vi plijunuloj, submetu vin al la pliaĝuloj. Tial ankaŭ vi ĉiuj submetu vin unu al la alia, kaj zonu vin per humileco; ĉar Dio kontraŭstaras al la fieruloj, sed al la humiluloj donas gracon."],[5,6,"Humiligu vin do sub la potencan manon de Dio, por ke Li altigu vin ĝustatempe;","Humiligu vin do sub la potencan manon de Dio, por ke Li altigu vin ĝustatempe;"],[5,7,"surĵetante sur Lin ĉian vian zorgon, ĉar Li zorgas pri vi.","surĵetante sur Lin ĉian vian zorgon, ĉar Li zorgas pri vi."],[5,8,"Estu sobraj, vigladu; via kontraŭulo, la diablo, kiel leono blekeganta ĉirkaŭiras, serĉante, kiun li povos forgluti;","Estu sobraj, vigladu; via kontraŭulo, la diablo, kiel leono blekeganta ĉirkaŭiras, serĉante, kiun li povos forgluti;"],[5,9,"lin rezistu, konstantaj en la fido, sciante, ke la samaj suferoj plenumiĝas en via frataro en la mondo.","lin rezistu, konstantaj en la fido, sciante, ke la samaj suferoj plenumiĝas en via frataro en la mondo."],[5,10,"Kaj la Dio de ĉia graco, kiu vin alvokis al Sia eterna gloro en Kristo, mem perfektigos, firmigos, plifortigos vin ne longe suferintajn.","Kaj la Dio de ĉia graco, kiu vin alvokis al Sia eterna gloro en Kristo, mem perfektigos, firmigos, plifortigos vin ne longe suferintajn."],[5,11,"Al Li estu la potenco por ĉiam kaj eterne. Amen.","Al Li estu la potenco por ĉiam kaj eterne. Amen."],[5,12,"Per Silvano, la fidela frato, kiel mi opinias, al vi mi skribis mallonge, konsilante kaj atestante, ke ĉi tio estas la vera graco de Dio; en ĝi firme staru.","Per Silvano, la fidela frato, kiel mi opinias, al vi mi skribis mallonge, konsilante kaj atestante, ke ĉi tio estas la vera graco de Dio; en ĝi firme staru."],[5,13,"Vin salutas la en Babel kunelektitino, kaj Marko, mia filo.","Vin salutas la en Babel kunelektitino, kaj Marko, mia filo."],[5,14,"Salutu unu la alian per ama kiso. Paco al vi ĉiuj, kiuj estas en Kristo.","Salutu unu la alian per ama kiso. Paco al vi ĉiuj, kiuj estas en Kristo."]]}};